import { CONFIG } from '../../config';
import { genTile, type TileResult } from './tileGen';

interface Tile {
  canvas: HTMLCanvasElement;
  used: number;
}

interface Req {
  key: string;
  level: number;
  tx: number;
  tz: number;
  prio: number;
}

interface WorkerSlot {
  w: Worker;
  busy: number;
  dead: boolean;
}

const tileKey = (l: number, x: number, z: number) => `${l}:${x}:${z}`;

/**
 * Map tile cache: LRU of small canvases, generated by a pool of workers (main-thread time-sliced fallback when
 * workers are unavailable). The renderer calls need() for every missing visible tile each render, then flush().
 */
export class TileCache {
  private tiles = new Map<string, Tile>();
  private pending = new Map<number, Req>();
  private pendingKeys = new Set<string>();
  private queue: Req[] = [];
  private workers: WorkerSlot[] = [];
  private nextId = 1;
  private frame = 0;
  private fallbackTimer = 0;
  private failed = new Set<string>();
  /** Called when a tile arrives (the renderer re-renders). */
  onTile: (() => void) | null = null;

  constructor() {
    const n = Math.max(1, Math.min(CONFIG.nav.mapWorkers, Math.max(1, (navigator.hardwareConcurrency || 2) - 1)));
    for (let i = 0; i < n; i++) {
      try {
        const w = new Worker(new URL('./tileWorker.ts', import.meta.url), { type: 'module' });
        const slot: WorkerSlot = { w, busy: 0, dead: false };
        w.onmessage = (e) => this.onMessage(slot, e.data);
        w.onerror = (e) => {
          console.warn('[map] tile worker failed, falling back to the main thread', e.message);
          slot.dead = true;
          this.requeueAll();
        };
        w.postMessage({ type: 'init', seed: CONFIG.game.seed, coast: { ...CONFIG.world.coast }, waterLevel: CONFIG.world.waterLevel });
        this.workers.push(slot);
      } catch (err) {
        console.warn('[map] workers unavailable', err);
        break;
      }
    }
  }

  get size(): number {
    return this.tiles.size;
  }

  get busy(): boolean {
    return this.pending.size > 0 || this.queue.length > 0;
  }

  beginFrame(): void {
    this.frame++;
    this.queue.length = 0;
  }

  get(level: number, tx: number, tz: number): HTMLCanvasElement | null {
    const t = this.tiles.get(tileKey(level, tx, tz));
    if (!t) return null;
    t.used = this.frame;
    return t.canvas;
  }

  has(level: number, tx: number, tz: number): boolean {
    return this.tiles.has(tileKey(level, tx, tz));
  }

  need(level: number, tx: number, tz: number, prio: number): void {
    const key = tileKey(level, tx, tz);
    if (this.tiles.has(key) || this.pendingKeys.has(key) || this.failed.has(key)) return;
    this.queue.push({ key, level, tx, tz, prio });
  }

  flush(): void {
    if (!this.queue.length) return;
    this.queue.sort((a, b) => a.prio - b.prio);
    const live = this.workers.filter((s) => !s.dead);
    if (live.length) {
      for (const s of live) {
        while (s.busy < 2 && this.queue.length) {
          const r = this.queue.shift()!;
          if (this.pendingKeys.has(r.key)) continue;
          const id = this.nextId++;
          this.pending.set(id, r);
          this.pendingKeys.add(r.key);
          s.busy++;
          s.w.postMessage({ type: 'tile', id, level: r.level, tx: r.tx, tz: r.tz, size: CONFIG.nav.mapTilePx });
        }
      }
    } else if (!this.fallbackTimer) {
      this.fallbackTimer = window.setTimeout(() => this.fallbackSlice(), 0);
    }
  }

  private fallbackSlice(): void {
    this.fallbackTimer = 0;
    const t0 = performance.now();
    while (this.queue.length && performance.now() - t0 < 10) {
      const r = this.queue.shift()!;
      if (this.tiles.has(r.key)) continue;
      try {
        const res = genTile({ level: r.level, tx: r.tx, tz: r.tz, size: CONFIG.nav.mapTilePx });
        this.store(r, res);
      } catch (err) {
        console.warn('[map] tile failed', err);
        this.failed.add(r.key);
      }
    }
    this.onTile?.();
    if (this.queue.length) this.fallbackTimer = window.setTimeout(() => this.fallbackSlice(), 16);
  }

  private onMessage(slot: WorkerSlot, m: { type: string; id: number; pixels?: ArrayBuffer; segs?: ArrayBuffer; msg?: string }): void {
    const r = this.pending.get(m.id);
    slot.busy = Math.max(0, slot.busy - 1);
    if (r) {
      this.pending.delete(m.id);
      this.pendingKeys.delete(r.key);
      if (m.type === 'tile' && m.pixels) {
        this.store(r, { pixels: new Uint8ClampedArray(m.pixels), segs: new Float32Array(m.segs ?? new ArrayBuffer(0)) });
      } else {
        this.failed.add(r.key);
        if (m.msg) console.warn('[map] tile error', m.msg);
      }
    }
    this.flush();
    this.onTile?.();
  }

  private requeueAll(): void {
    for (const r of this.pending.values()) this.queue.push(r);
    this.pending.clear();
    this.pendingKeys.clear();
    this.flush();
  }

  private store(r: Req, res: TileResult): void {
    const size = CONFIG.nav.mapTilePx;
    if (res.pixels.length !== size * size * 4) return;
    const c = document.createElement('canvas');
    c.width = size;
    c.height = size;
    const g = c.getContext('2d');
    if (!g) return;
    g.putImageData(new ImageData(res.pixels as unknown as Uint8ClampedArray<ArrayBuffer>, size, size), 0, 0);
    // seeded highway corridors on top (casing, then deck)
    const s = res.segs;
    if (s.length) {
      g.lineCap = 'round';
      g.lineJoin = 'round';
      for (let pass = 0; pass < 2; pass++) {
        for (let i = 0; i + 5 < s.length; i += 6) {
          const kind = s[i + 5];
          const w = s[i + 4];
          g.beginPath();
          g.moveTo(s[i], s[i + 1]);
          g.lineTo(s[i + 2], s[i + 3]);
          if (pass === 0) {
            g.setLineDash([]);
            g.strokeStyle = kind === 1 ? 'rgba(255,255,255,0.95)' : kind === 2 ? 'rgba(70,64,90,0.35)' : 'rgba(150,80,40,0.55)';
            g.lineWidth = w + (kind === 1 ? 2.4 : 1.6);
          } else {
            g.strokeStyle = kind === 2 ? 'rgba(244,162,107,0.55)' : '#f4a26b';
            g.lineWidth = w;
            g.setLineDash(kind === 2 ? [Math.max(2, w * 1.5), Math.max(2, w * 1.2)] : []);
          }
          g.stroke();
        }
      }
      g.setLineDash([]);
    }
    this.tiles.set(r.key, { canvas: c, used: this.frame });
    this.evict();
  }

  private evict(): void {
    const max = Math.max(32, CONFIG.nav.mapTileCache);
    if (this.tiles.size <= max) return;
    const arr = Array.from(this.tiles.entries()).sort((a, b) => a[1].used - b[1].used);
    const drop = this.tiles.size - Math.floor(max * 0.85);
    for (let i = 0; i < drop; i++) {
      const [k, t] = arr[i];
      t.canvas.width = 0;
      t.canvas.height = 0;
      this.tiles.delete(k);
    }
  }

  /** Drop queued (not in-flight) requests — the map closed. */
  cancelQueued(): void {
    this.queue.length = 0;
  }

  dispose(): void {
    for (const s of this.workers) s.w.terminate();
    this.workers.length = 0;
    for (const t of this.tiles.values()) {
      t.canvas.width = 0;
      t.canvas.height = 0;
    }
    this.tiles.clear();
  }
}
